ALTER TABLE "agent_runs" ADD CONSTRAINT "agent_runs_fake_model_usage_check" CHECK (("workflow_version" = 'deep-match-v1' and jsonb_typeof("model_snapshot") = 'object') or ("workflow_version" in ('job-discovery-workflow-v2', 'job-discovery-workflow-v3', 'layered-public-job-discovery-v1') and (jsonb_typeof("model_snapshot") = 'object' or ("model_snapshot" is null and "model_call_count" = 0 and "input_token_count" = 0 and "output_token_count" = 0 and "total_token_count" = 0))) or ("workflow_version" = 'job-discovery-workflow-v1' and "model_snapshot" is null and "model_call_count" = 0 and "input_token_count" = 0 and "output_token_count" = 0 and "total_token_count" = 0));
